/* dashboard.min.js (improved to include Attachment Executed in dashboard) */
var campaigns=[],
    statuses={
      "Email Sent":{color:"#1abc9c",label:"label-success",icon:"fa-envelope",point:"ct-point-sent"},
      "Emails Sent":{color:"#1abc9c",label:"label-success",icon:"fa-envelope",point:"ct-point-sent"},
      "In progress":{label:"label-primary"},
      Queued:{label:"label-info"},
      Completed:{label:"label-success"},
      "Email Opened":{color:"#f9bf3b",label:"label-warning",icon:"fa-envelope-open",point:"ct-point-opened"},
      "Email Reported":{color:"#45d6ef",label:"label-warning",icon:"fa-bullhorn",point:"ct-point-reported"},
      "Clicked Link":{color:"#F39C12",label:"label-clicked",icon:"fa-mouse-pointer",point:"ct-point-clicked"},
      Success:{color:"#f05b4f",label:"label-danger",icon:"fa-exclamation",point:"ct-point-clicked"},
      Error:{color:"#6c7a89",label:"label-default",icon:"fa-times",point:"ct-point-error"},
      "Error Sending Email":{color:"#6c7a89",label:"label-default",icon:"fa-times",point:"ct-point-error"},
      "Submitted Data":{color:"#f05b4f",label:"label-danger",icon:"fa-exclamation",point:"ct-point-clicked"},
      "Attachment Executed":{color:"#ff0000",label:"label-danger",icon:"fa-exclamation-triangle",point:"ct-point-executed"},
      Unknown:{color:"#6c7a89",label:"label-default",icon:"fa-question",point:"ct-point-error"},
      Sending:{color:"#428bca",label:"label-primary",icon:"fa-spinner",point:"ct-point-sending"},
      "Campaign Created":{label:"label-success",icon:"fa-rocket"}
    },
    // keys map to chart container ids: <key>_chart
    statsMapping={
      sent:"Email Sent",
      opened:"Email Opened",
      clicked:"Clicked Link",
      submitted_data:"Submitted Data",
      attachment_executed:"Attachment Executed",
      email_reported:"Email Reported"
    };

function deleteCampaign(i){
  if(!confirm("Delete "+campaigns[i].name+"?")) return;
  api.campaignId.delete(campaigns[i].id).success(function(resp){
    successFlash(resp.message); location.reload();
  });
}

function renderPieChart(opts){
  return Highcharts.chart(opts.elemId,{
    chart:{
      type:"pie",
      events:{
        load:function(){
          var chart=this, rend=chart.renderer, pie=chart.series[0],
              left=chart.plotLeft+pie.center[0], top=chart.plotTop+pie.center[1],
              p=(chart.series[0]&&chart.series[0].points&&chart.series[0].points[0])||null,
              count=p?((p.options&&p.options.count)||p.count||0):0;
          this.innerText=rend.text(count,left,top)
            .attr({"text-anchor":"middle","font-size":"16px","font-weight":"bold",fill:opts.colors[0],"font-family":"Helvetica,Arial,sans-serif"})
            .add();
        },
        render:function(){
          var p=(this.series[0]&&this.series[0].points&&this.series[0].points[0])||null,
              count=p?((p.options&&p.options.count)||p.count||0):0;
          this.innerText.attr({text:count});
        }
      }
    },
    title:{text:opts.title},
    plotOptions:{pie:{innerSize:"80%",dataLabels:{enabled:!1}}},
    credits:{enabled:!1},
    tooltip:{formatter:function(){return this.key!=null&&('<span style="color:'+this.color+'">●</span>'+this.point.name+": <b>"+this.y+"%</b><br/>")}},
    series:[{data:opts.data,colors:opts.colors}]
  });
}

/* Build { campaignId: executedCount } by scanning each campaign timeline */
function fetchAttachmentExecutedCounts(cs){
  var d=$.Deferred(), res={}, tasks=$.map(cs,function(c){
    var t=$.Deferred();
    api.campaignId.results(c.id).success(function(r){
      var seen={}, cnt=0, tl=r.timeline||[];
      for(var i=0;i<tl.length;i++){
        var ev=tl[i];
        if(ev && ev.email && ev.message==="Attachment Executed" && !seen[ev.email]){
          seen[ev.email]=true; cnt++;
        }
      }
      res[c.id]=cnt; t.resolve();
    }).error(function(){ res[c.id]=0; t.resolve(); });
    return t;
  });
  $.when.apply($,tasks).always(function(){ d.resolve(res); });
  return d.promise();
}

/* Build donuts for all statuses incl. Attachment Executed */
function generateStatsPieCharts(camps, execMap){
  var series=[], agg={}, total=0;
  $.each(camps,function(_,c){
    $.each(c.stats,function(k,v){
      if(k==="total"){ total+=v; return true; }
      agg[k]=(agg[k]||0)+v;
    });
    var ex=(c.stats && c.stats.attachment_executed!=null)?c.stats.attachment_executed:(execMap[c.id]||0);
    agg["attachment_executed"]=(agg["attachment_executed"]||0)+ex;
  });
  $.each(agg,function(k,val){
    if(!(k in statsMapping)) return true;
    var label=statsMapping[k],
        pct= total ? Math.floor(val/total*100) : 0;
    series.push({name:label,y:pct,count:val});
    series.push({name:"",y:100-pct});
    renderPieChart({elemId:k+"_chart",title:label,name:k,data:series,colors:[statuses[label].color,"#dddddd"]});
    series=[];
  });
}

/* Overview timeline chart (kept same logic: % clicked over total) */
function generateTimelineChart(cs){
  var data=[];
  $.each(cs,function(_,c){
    var ts=moment.utc(c.created_date).local();
    c.y=0;
    c.y+=c.stats.clicked;
    c.y=Math.floor(c.y/c.stats.total*100);
    data.push({campaign_id:c.id,name:c.name,x:ts.valueOf(),y:c.y});
  });
  Highcharts.chart("overview_chart",{
    chart:{zoomType:"x",type:"areaspline"},
    title:{text:"Phishing Success Overview"},
    xAxis:{type:"datetime",dateTimeLabelFormats:{second:"%l:%M:%S",minute:"%l:%M",hour:"%l:%M",day:"%b %d, %Y",week:"%b %d, %Y",month:"%b %Y"}},
    yAxis:{min:0,max:100,title:{text:"% of Success"}},
    tooltip:{formatter:function(){return Highcharts.dateFormat("%A, %b %d %l:%M:%S %P",new Date(this.x))+"<br>"+this.point.name+"<br>% Success: <b>"+this.y+"%</b>"}},
    legend:{enabled:!1},
    plotOptions:{series:{marker:{enabled:!0,symbol:"circle",radius:3},cursor:"pointer",point:{events:{click:function(){window.location.href="/campaigns/"+this.campaign_id}}}}},
    credits:{enabled:!1},
    series:[{data:data,color:"#f05b4f",fillOpacity:.5}]
  });
}

$(document).ready(function(){
  Highcharts.setOptions({global:{useUTC:!1}});
  api.campaigns.summary().success(function(resp){
    $("#loading").hide();
    campaigns = resp.campaigns;
    if(campaigns.length<=0){ $("#emptyMessage").show(); return; }

    $("#dashboard").show();
    var campaignTable=$("#campaignTable").DataTable({
      columnDefs:[
        {orderable:!1,targets:"no-sort"},
        {className:"color-sent",targets:[2]},     // Sent
        {className:"color-opened",targets:[3]},   // Opened
        {className:"color-clicked",targets:[4]},  // Clicked
        {className:"color-success",targets:[5]},  // Submitted
        {className:"color-executed",targets:[6]}, // Executed
        {className:"color-reported",targets:[7]}  // Reported
      ],
      order:[[1,"desc"]]
    });

    var campaignRows=[];
    fetchAttachmentExecutedCounts(campaigns).done(function(execMap){
      $.each(campaigns,function(i,c){
        var created = moment(c.created_date).format("MMMM Do YYYY, h:mm:ss a"),
            label   = (statuses[c.status]&&statuses[c.status].label)||"label-default",
            executed= (c.stats && c.stats.attachment_executed!=null)?c.stats.attachment_executed:(execMap[c.id]||0),
            tip;

        if(moment(c.launch_date).isAfter(moment())){
          tip = "Scheduled to start: "+moment(c.launch_date).format("MMMM Do YYYY, h:mm:ss a")+"<br><br>"+
                "Number of recipients: "+c.stats.total;
        }else{
          tip = "Launch Date: "+moment(c.launch_date).format("MMMM Do YYYY, h:mm:ss a")+"<br><br>"+
                "Number of recipients: "+c.stats.total+"<br><br>"+
                "Emails opened: "+c.stats.opened+"<br><br>"+
                "Emails clicked: "+c.stats.clicked+"<br><br>"+
                "Submitted Credentials: "+c.stats.submitted_data+"<br><br>"+
                "Attachments executed: "+executed+"<br><br>"+
                "Errors : "+c.stats.error+"<br><br>"+
                "Reported : "+c.stats.email_reported;
        }

        campaignRows.push([
          escapeHtml(c.name),
          created,
          c.stats.sent,
          c.stats.opened,
          c.stats.clicked,
          c.stats.submitted_data,
          executed,                // Executed column
          c.stats.email_reported,
          '<span class="label '+label+'" data-toggle="tooltip" data-placement="right" data-html="true" title="'+tip+'">'+c.status+'</span>',
          "<div class='pull-right'>"+
            "<a class='btn btn-primary' href='/campaigns/"+c.id+"' data-toggle='tooltip' data-placement='left' title='View Results'>"+
              "<i class='fa fa-bar-chart'></i></a> "+
            "<button class='btn btn-danger' onclick='deleteCampaign("+i+")' data-toggle='tooltip' data-placement='left' title='Delete Campaign'>"+
              "<i class='fa fa-trash-o'></i></button>"+
          "</div>"
        ]);
      });

      campaignTable.rows.add(campaignRows).draw();
      $('[data-toggle="tooltip"]').tooltip();

      // Build pies and overview
      generateStatsPieCharts(campaigns, execMap);
      generateTimelineChart(campaigns);
    });

  }).error(function(){
    errorFlash("Error fetching campaigns");
  });
});

